const input = $input.first().json;
const body = input.body || input;

// Required fields
const command = (body.command || '').toLowerCase().trim();
const postId = body.post_id;
const callbackUrl = body.callback_url || '';
const authToken = body.auth_token || '';
const notificationUrl = body.notification_url || '';

// The plugin's test ping: Ping OK sends the item on to POST Result to WordPress, which calls the site back
// at callback_url with auth_token (the round trip, story 2). One line: the stamp below stays the one the Free derivation reads.
if (command === 'ping') {
  return [{ json: { command: 'ping', ping: true, error: false, callback_url: callbackUrl, auth_token: authToken, notification_url: '', workflow_version: 11 } }];
}

if (!command || !postId) {
  return [{ json: { error: true, message: 'Missing required fields: command, post_id' } }];
}

const validCommands = ['score', 'review', 'takeaways', 'apply'];
if (!validCommands.includes(command)) {
  return [{ json: { error: true, message: 'Unknown command: ' + command } }];
}

return [{ json: {
  command,
  callback_url: callbackUrl,
  auth_token: authToken,
  notification_url: notificationUrl,
  post_id: postId,
  slug: body.slug || '',
  post_type: body.post_type || 'post',
  title: body.title || '',
  link: body.link || '',
  post_rest_url: body.post_rest_url || '',
  excerpt: body.excerpt || '',
  content: body.content || '',
  content_html: body.content_html || '',
  seo_score: body.seo_score || 0,
  readability_score: body.readability_score || 0,
  focus_keyphrase: body.focus_keyphrase || '',
  meta_description: body.meta_description || '',
  seo_title: body.seo_title || '',
  brand_voice: body.brand_voice || '',
  website_context: body.website_context || '',
  agent_prompts: body.agent_prompts || {},
  llm: body.llm || {},
  workflow_version: 11,
  workflow_variant: 'free',
  error: false
}}];

const d = $input.first().json;
if (!d.title) {
  return [{ json: { ...d, error: true, message: 'Post not found.' } }];
}

// Format a basic score result from the Yoast data already in the payload.
const rawSEO = parseInt(d.seo_score) || 0;
const rawRead = parseInt(d.readability_score) || 0;

const result = {
  seo_score: rawSEO,
  readability_score: rawRead,
  focus_keyphrase: d.focus_keyphrase || '',
  meta_description: d.meta_description || '',
  title: d.title,
  link: d.link
};

// Determine overall: average of SEO and readability.
const overall = rawSEO && rawRead ? Math.round((rawSEO + rawRead) / 2) : rawSEO || rawRead || 0;
const status = overall >= 71 ? 'ship' : overall >= 41 ? 'needs_revision' : 'major_revision';

// Format for chat notification
const getLabel = (raw) => {
  if (raw === 0) return { score: 'N/A', emoji: '⚪', label: 'Not yet scored' };
  const s = (raw / 10).toFixed(1);
  if (raw >= 71) return { score: s, emoji: '🟢', label: 'Good' };
  if (raw >= 41) return { score: s, emoji: '🟠', label: 'Needs improvement' };
  return { score: s, emoji: '🔴', label: 'Needs work' };
};
const seo = getLabel(rawSEO);
const read = getLabel(rawRead);
const chatMsg = [
  '### 📊 Post Score Report', '',
  '**📝 ' + d.title + '**', '🔗 ' + d.link, '', '---', '',
  '| Metric | Score | Status |', '|:---|:---:|:---|',
  '| 🔍 Yoast SEO | ' + seo.score + '/10 | ' + seo.emoji + ' ' + seo.label + ' |',
  '| 📖 Readability | ' + read.score + '/10 | ' + read.emoji + ' ' + read.label + ' |',
  '', '🎯 **Focus keyphrase:** ' + (d.focus_keyphrase ? '`' + d.focus_keyphrase + '`' : '_not set_'),
  '📋 **Meta description:** ' + (d.meta_description ? d.meta_description.substring(0, 100) : '_not set_')
].join('\n');

return [{ json: {
  ...d,
  overall_score: overall,
  status,
  result: JSON.stringify(result),
  chat_message: chatMsg
}}];

const d = $input.first().json;
if (!d.title || !d.content) {
  return [{ json: { error: true, message: 'Post not found or empty.' } }];
}

const guidelines = d._guidelines || '';

const userMsg = `Title: ${d.title}

Excerpt: ${d.excerpt}

Guidelines:
${guidelines}

Full article:
${d.content}`;
// Request params (model, max_tokens, temperature/effort/thinking) are built by the plugin and travel in the payload.
const llm = d.llm?.review || { model: "claude-sonnet-4-6", max_tokens: 2500 };
const body = {
  ...llm,
  system: "You are a Senior Content Reviewer for " + (d.website_context || "a general audience blog") + ".

TONE & VOICE RULES:
" + (d.brand_voice || "- Professional yet accessible
- Active voice preferred") + "

AGNOSTIC SCORING FRAMEWORK (Score each 0-100):
1. Structure: Logical flow, clear hierarchy (H2/H3s), and coherent pacing.
2. Readability: Accessibility, concise sentences, avoiding heavy jargon.
3. Engagement: The hook, emotional resonance, preventing drop-offs, and actionable value.
4. Credibility (E-E-A-T): Trustworthiness, evidence-backed claims, and expert tone.

SCORING CALIBRATION:
Rubric (apply to every 0-100 score):
  90-100  Exceptional (publish-ready, top 1%)
  75-89   Strong (great but needs minor tweaks)
  60-74   Decent (average, needs better flow/hooks)
  40-59   Weak (poorly structured, unsupported claims)
  0-39    Poor (unpublishable draft quality)

Status (must match overall_score):
  "ship"            -> overall_score >= 71
  "needs_revision"  -> overall_score 41-70
  "major_revision"  -> overall_score <= 40


" + (d.agent_prompts?.review?.instructions ? "ADDITIONAL INSTRUCTIONS:
" + d.agent_prompts.review.instructions + "

" : "") + "Return ONLY valid JSON, no markdown, no explanation:
{
  "overall_score": 0-100,
  "status": "ship | needs_revision | major_revision",
  "structure": { "score": 0-100, "issues": [], "suggestions": [] },
  "readability": { "score": 0-100, "issues": [], "suggestions": [] },
  "engagement": { "score": 0-100, "issues": [], "suggestions": [] },
  "credibility": { "score": 0-100, "issues": [], "suggestions": [] },
  "top_edits": ["edit 1", "edit 2", "edit 3"]
}
Limit issues and suggestions to 3 per dimension. top_edits must contain exactly 3 items.",
  messages: [{ role: "user", content: userMsg }]
};
return [{ json: { ...d, claudeBody: JSON.stringify(body) } }];

const resp = $input.first().json;
const d = $('Parse Input').first().json;
const built = $('Build Review Body').first().json;
if (built.error === true) {
  return [{ json: { ...d, error: true, message: 'Review Agent: ' + built.message } }];
}
if (resp.error) {
  const apiText = typeof resp.error === 'string' ? resp.error : (typeof resp.error?.error === 'string' ? resp.error.error : (resp.error?.error?.error?.message || resp.error?.error?.message || resp.error?.description || resp.error?.message || 'no details returned'));
  return [{ json: { ...d, error: true, message: 'Review Agent could not get an answer from the model: ' + apiText } }];
}
let r;
try {
  const text = ((resp.content || []).find(b => b.type === 'text')?.text || '').replace(/^\s*(?:<thinking>[\s\S]*?<\/thinking>\s*)+/i, '');
  const raw = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
  r = JSON.parse(raw);
} catch(e) {
  return [{ json: { ...d, error: true, message: 'Review Agent returned invalid JSON.' } }];
}

const noResult = [{ json: { ...d, error: true, message: 'Review Agent returned no usable result. Run the command again.' } }];
// The fields the score and status come from: a reply without one holds no result.
// The site stores a whole-number score, from a number or a string holding one; the status is one of the prompt's three values.
const given = r.overall_score;
const score = (typeof given === 'number' || (typeof given === 'string' && given.trim() !== '')) ? Math.round(Number(given)) : NaN;
if (!Number.isFinite(score) || !['ship', 'needs_revision', 'major_revision'].includes(r.status)) {
  return noResult;
}
try {
  const se = (s) => s >= 71 ? '🟢' : s >= 41 ? '🟠' : '🔴';
  const fmt = (s) => (s/10).toFixed(1) + '/10';
  const statusMap = { ship: '🟢 Ready to ship', needs_revision: '🟠 Needs revision', major_revision: '🔴 Major revision needed' };

  const lines = [
    '### ✍️ Content Review Report', '',
    '**📝 ' + d.title + '**', '🔗 ' + d.link, '', '---', '',
    '| Dimension | Score | Status |', '|:---|:---:|:---|',
    '| 🏗 Structure | ' + fmt(r.structure?.score||0) + ' | ' + se(r.structure?.score||0) + ' |',
    '| 📖 Readability | ' + fmt(r.readability?.score||0) + ' | ' + se(r.readability?.score||0) + ' |',
    '| 💡 Engagement | ' + fmt(r.engagement?.score||0) + ' | ' + se(r.engagement?.score||0) + ' |',
    '| 🛡️ Credibility | ' + fmt(r.credibility?.score||0) + ' | ' + se(r.credibility?.score||0) + ' |',
    '', '---', '',
    '🔧 **Top edits:**',
    ...(r.top_edits||[]).map((e,i) => (i+1) + '. ' + e),
    '', '**Overall: ' + (statusMap[r.status] || r.status) + '** (' + fmt(r.overall_score||0) + ')'
  ];

  return [{ json: {
    ...d,
    overall_score: score,
    status: r.status || 'needs_revision',
    result: JSON.stringify(r),
    chat_message: lines.join('\n'),
    error: false
  }}];
} catch(e) {
  return noResult;
}

const d = $input.first().json;
if (!d.title || !d.content_html) {
  return [{ json: { error: true, message: 'Post not found or empty.' } }];
}
const userMsg = `Title: ${d.title}

Raw HTML:
${d.content_html}`;
const llm = d.llm?.takeaways || { model: "claude-sonnet-4-6", max_tokens: 1000 };
const body = {
  ...llm,
  system: "You are a Key Takeaways reviewer for a blog.

KEY TAKEAWAYS BLOCK RULES:
- Must exist in the article
- Must be the very first element
- Must contain 3 to 5 items
- Each item: informative, specific, declarative, 25 words or fewer
- Items must not repeat each other

FEW-SHOT EXAMPLES:
Bad: "The article discusses the importance of sleep."
Good: "Prioritize 8 hours of sleep to improve cognitive function by 20%."


" + (d.agent_prompts?.takeaways?.instructions ? "ADDITIONAL INSTRUCTIONS:
" + d.agent_prompts.takeaways.instructions + "

" : "") + "Return ONLY valid JSON:
{
  "block_found": true,
  "position_correct": true,
  "position_note": "...",
  "count": 0,
  "count_ok": true,
  "items_within_word_limit": true,
  "items_are_specific": true,
  "issues": [],
  "current_items": [],
  "rewritten_items": []
}
Limit issues to 3. Always provide rewritten_items (3-5 items).",
  messages: [{ role: "user", content: userMsg }]
};
return [{ json: { ...d, claudeBody: JSON.stringify(body) } }];

const resp = $input.first().json;
const d = $('Parse Input').first().json;
const built = $('Build Takeaways Body').first().json;
if (built.error === true) {
  return [{ json: { ...d, error: true, message: 'Takeaways Agent: ' + built.message } }];
}
if (resp.error) {
  const apiText = typeof resp.error === 'string' ? resp.error : (typeof resp.error?.error === 'string' ? resp.error.error : (resp.error?.error?.error?.message || resp.error?.error?.message || resp.error?.description || resp.error?.message || 'no details returned'));
  return [{ json: { ...d, error: true, message: 'Takeaways Agent could not get an answer from the model: ' + apiText } }];
}
let r;
try {
  const text = ((resp.content || []).find(b => b.type === 'text')?.text || '').replace(/^\s*(?:<thinking>[\s\S]*?<\/thinking>\s*)+/i, '');
  const raw = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
  r = JSON.parse(raw);
} catch(e) {
  return [{ json: { ...d, error: true, message: 'Takeaways Agent returned invalid JSON.' } }];
}

const noResult = [{ json: { ...d, error: true, message: 'Takeaways Agent returned no usable result. Run the command again.' } }];
// The fields the score and status come from: a reply without one holds no result.
// Only a found block (block_found true) needs the other three checks; a null check is an answer, read as false.
if (r.block_found == null || (r.block_found === true && [r.position_correct, r.count_ok, r.items_are_specific].some(v => v === undefined))) {
  return noResult;
}
try {
  const chk = (v) => v ? '✅' : '❌';
  const lines = [
    '### 🔑 Key Takeaways Review', '',
    '**📝 ' + d.title + '**', '🔗 ' + d.link, '', '---', '',
    '| Check | Status |', '|:---|:---:|',
    '| Block found | ' + chk(r.block_found) + ' |',
    '| Position correct | ' + chk(r.position_correct) + ' |',
    '| Count (3-5) | ' + chk(r.count_ok) + ' (' + r.count + ') |',
    '| Items ≤ 25 words | ' + chk(r.items_within_word_limit) + ' |',
    '| Items specific | ' + chk(r.items_are_specific) + ' |'
  ];
  if (r.issues && r.issues.length > 0) {
    lines.push('', '---', '', '⚠️ **Issues:**');
    r.issues.forEach(i => lines.push('- ' + i));
  }
  lines.push('', '---', '', '✏️ **Suggested rewrite:**');
  (r.rewritten_items || []).forEach((item, i) => lines.push((i+1) + '. ' + item));

  // score: all checks pass = 80, else 50
  const score = (r.block_found && r.position_correct && r.count_ok && r.items_are_specific) ? 80 : 50;
  const status = score >= 71 ? 'ship' : 'needs_revision';

  return [{ json: {
    ...d,
    overall_score: score,
    status,
    result: JSON.stringify(r),
    chat_message: lines.join('\n'),
    error: false
  }}];
} catch(e) {
  return noResult;
}

// Connectivity test: the webhook already answered 200 on receipt. The item goes on to POST Result to WordPress,
// which calls the site back at callback_url with auth_token: the plugin waits for that call and reports the round trip.
const d = $input.first().json;
return [{ json: { ...d, overall_score: 0, status: '', result: '{}' } }];

// Error fallback: a command this workflow has no branch for.
const d = $input.first().json;
const message = d.message || 'This workflow has no step for the "' + (d.command || '') + '" command.';
return [{ json: { ...d, error: true, message, overall_score: 0, status: '', result: '{}', chat_message: '❌ ' + message } }];
